    9 => [
        // === 1. ОБЩАЯ ХАРАКТЕРИСТИКА ===
        'title' => 'ГОД ЗАВЕРШЕНИЙ И ТРАНСФОРМАЦИИ',
        'subtitle' => 'Время отпускать, прощать и подводить итоги',
        'deed' => 'Завершение, прощение, отпускание, трансформация, итоги, мудрость, сострадание, бескорыстие, жертвенность, искусство, творчество, философия, религия, смерть (символическая), перерождение, целостность, гуманизм, благотворительность, помощь',
        'element' => 'Огонь (трансформация) / Вода (очищение)',
        'planet' => 'Нептун (мистика, растворение), Марс (очищение огнём), Плутон (трансформация, смерть и возрождение)',
        'archetype' => 'Отшельник, Мудрец, Жертва (символическая), Целитель, Художник, Философ, Гуманист, Прощающий',
        
        // === 2. ГЛОБАЛЬНЫЙ СМЫСЛ ===
        'meaning' => 'Это год итогов, очищения и отпускания. Вам предстоит завершить старые дела, расстаться с тем, что отжило — вещами, людьми, работой, привычками. Год может быть эмоционально трудным, но он освободит место для нового девятилетнего цикла. Не начинайте ничего крупного — лучше помогайте другим, занимайтесь благотворительностью, подводите итоги. Прощайте обиды и отпускайте прошлое. Завершение — это не конец, а подготовка к новому. Девятка — самое духовное число. Она учит безусловной любви, прощению, принятию. Год может принести разочарования, потери, но это необходимо для вашего роста. Ваша задача — пройти через это с достоинством, не озлобиться, а стать мудрее. Вы будете видеть людей насквозь, их истинную суть. Многие маски упадут. Это больно, но это очищение. Вам захочется уединения, размышлений, творчества. Подводите итоги 9-летнего цикла: что вы достигли, в чём выросли, какие ошибки совершили. Простите себя и других.',
        
        'tasks' => 'Главные задачи года: (1) Завершить все незавершённые дела, проекты, отношения. (2) Простить обиды и попросить прощения у тех, кого обидели. (3) Избавиться от ненужных вещей, долгов, вредных привычек. (4) Подвести итоги 9-летнего цикла: что достигнуто, чему научились. (5) Помочь тем, кто слабее (благотворительность, волонтёрство). (6) Заняться творчеством для души, а не для денег. (7) Понять своё предназначение, ответить на вопрос "Зачем я живу?". (8) Развить сострадание и эмпатию, научиться безусловной любви. (9) Отпустить контроль над будущим, довериться Вселенной. (10) Подготовиться к новому 9-летнему циклу (поставить цели).',
        
        'karmic_lesson' => 'Кармический урок года — научиться отпускать. В прошлых воплощениях вы могли цепляться за людей, вещи, ситуации, бояться перемен. Этот год учит: всё временно. Чтобы пришло новое, нужно освободить место. Кармическая задача: завершить старые кармические связи, отработать долги (помочь тем, кому должны), простить обидчиков. Особое внимание уделите кармическим "хвостам" из детства и юности. Не берите кармических долгов на будущее (не обижайте, не обманывайте). Ваша душа должна войти в новый цикл чистой, без груза прошлого. Кармический вызов: не впасть в отчаяние от потерь, не озлобиться. Понимайте, что всё, что уходит, — не ваше. Благодарите за опыт и отпускайте. Если вы чувствуете, что "не завершили", организуйте встречи, закройте гештальты.',
        
        'challenges' => 'Главные вызовы года: (1) Преодолеть страх перед переменами, даже если они болезненны. (2) Не впасть в депрессию из-за потерь и разочарований. (3) Не цепляться за прошлое, уметь отпускать. (4) Избегать чувства вины за то, что "не успел", "не доделал". (5) Не обвинять других в своих проблемах, взять ответственность. (6) Справляться с чувством одиночества, даже если вокруг люди. (7) Не зацикливаться на завершениях, видеть перспективу. (8) Не пренебрегать здоровьем на фоне стресса. (9) Не становиться жертвой мошенников, играя на сострадании. (10) Не откладывать прощение, оно важно для завершения цикла.',
        
        'pitfalls' => 'Подводные камни года: (1) Депрессия, апатия, чувство бессмысленности. (2) Потеря близких (смерть, расставание) — эмоционально тяжело. (3) Финансовые потери (завершение проектов, увольнение). (4) Проблемы со здоровьем (психосоматика, запущенные болезни). (5) Конфликты на почве дележа наследства, имущества. (6) Ощущение, что "жизнь прошла зря". (7) Одиночество, даже среди людей. (8) Разрыв многолетних дружеских и семейных связей. (9) Чувство вины перед ушедшими. (10) Нежелание начинать новое, страх перед будущим.',
        
        // === 3. СФЕРЫ ЖИЗНИ ===
        'career' => 'Карьера в году девятки — это завершение этапов. Не начинайте новых проектов, лучше заканчивайте старые. Возможно увольнение, сокращение, выход на пенсию, переход на менее ответственную работу. Год не для карьерного роста, а для подведения итогов. Если вы завершили крупный проект, отпразднуйте и не берите новый. Успешны профессии, связанные с помощью людям: психолог, врач, учитель, социальный работник, священник, волонтёр, целитель. Творческие профессии: писатель (пишите итоговые книги), художник (выставки-ретроспективы). Если вы руководитель, готовьтесь к передаче дел, ищите преемника. Не держитесь за кресло. Фриланс: завершайте заказы и не берите новые до января. Смена работы: нежелательна, лучше остаться до следующего года. Возможно возвращение на старое место, если есть незавершённые дела. Карьерные цели года: завершить, передать, проанализировать, уйти красиво.',
        
        'business' => 'Бизнес в году девятки — это закрытие или передача. Если бизнес себя изжил, лучше его закрыть или продать. Не начинайте новых бизнес-проектов, не берите кредитов. Завершайте договоры, собирайте долги, раздавайте долги. Благотворительность станет частью бизнеса: направьте часть прибыли на помощь нуждающимся. Возможно, вы продадите бизнес и выйдете из него, или передадите по наследству. Не расширяйтесь, не масштабируйтесь. Владельцам малого бизнеса: можно сменить сферу на более гуманитарную. Идеальный бизнес: благотворительный фонд, социальное предприятие. Маркетинг: не агрессивный, а просветительский, с акцентом на помощь. Участвуйте в благотворительных акциях. Если бизнес прибыльный, но не несёт пользы, задумайтесь о редизайне. Лучшее время для завершения — осень. Не поддавайтесь соблазну быстрых денег — обманут.',
        
        'money' => 'Финансовый прогноз года девятки нестабилен. Доходы могут упасть, но это временно. Не паникуйте. Главное — не влезать в долги, не брать кредитов. Отдавайте старые долги. Крупные траты только на самое необходимое. Экономьте, но не на еде и лечении. Благотворительность: отдавайте 10-20% от доходов, но не в ущерб себе. Это поможет деньгам не уходить окончательно. Не вкладывайте деньги в сомнительные проекты, не играйте на бирже. Сбережения лучше перевести в валюту или золото (консервативно). Если увольняют, не бойтесь, возможно, это шанс найти себя. Подушка безопасности должна быть на 6-12 месяцев. Не давайте в долг — не отдадут. Хорошо для получения наследства или подарков, но это тоже "завершение" (уход кого-то). Лучшее время для финансов — начало года (завершить прошлогодние проекты) и осень (подведение итогов). Не ввязывайтесь в финансовые авантюры, даже если кажется выгодным.',
        
        'love' => 'Любовь и отношения в году девятки — это завершение кармических связей. Для пар: год может принести разрыв. Если отношения себя изжили, они закончатся. Не держитесь за то, что не приносит радости. Если вы расстались, простите и отпустите. Если отношения крепкие, они выдержат испытание, но могут временно отдалиться (из-за вашей погружённости в себя). Возможно, вы уйдёте в монастырь или на время ретрита. Для одиноких: год не для новых отношений. Займитесь любовью к себе. Новый партнёр появится в следующем году. Избегайте романов с замужними/женатыми — они принесут боль. Беременность: нежелательна, если это не замыкание цикла. Лучше подождать до следующего года. Чего избегать: ревности, контроля, манипуляций, чувства вины, сцен. Если вам больно, уйдите в творчество, помогите другим. Любовь в этом году — это не страсть, а сострадание, принятие, дружба.',
        
        'family' => 'Семья в году девятки может сильно измениться. Возможно, кто-то уйдёт из жизни (смерть, расставание), или, наоборот, вернётся после долгой разлуки. Будьте готовы к переменам в составе семьи. Старые обиды могут всплыть — простите, отпустите. Дети могут уехать учиться, в армию, жениться — отпустите их. Родителям, возможно, потребуется уход, или наоборот, вы поможете им уйти (символически). Если вы чувствуете вину перед ушедшими, простите себя и их. Год подходит для "Дня поминовения" предков, поездки на кладбище. В доме: избавьтесь от хлама, раздайте ненужные вещи, проведите "генеральную уборку" энергетики. Не делайте ремонт (если не течёт крыша), но можно перекрасить стены в светлые тона. Семейные традиции: пересмотрите, какие устарели, откажитесь от них. Новые не вводите до следующего года. Если вы живёте с токсичными родственниками, найдите возможность съехать или дистанцироваться. Главное в семье — мир и прощение.',
        
        'friends' => 'Дружба в году девятки — это фильтр. Многие друзья уйдут из вашей жизни, и это нормально. Вы разочаруетесь в некоторых, другие просто исчезнут. Не держитесь за них. Останутся те, кто прошёл с вами весь цикл. Возможно, вы встретите друзей из прошлого (детства, юности), с которыми не общались годами. Это кармические встречи для завершения. Общение с ними может быть кратким, но значимым. Не бойтесь инициировать встречи и прощения. Если друг нуждается в помощи (финансовой, эмоциональной), помогите, но бескорыстно, не ожидая возврата. Дружба в соцсетях: отпишитесь от тех, кто вам неприятен. Не вступайте в споры, это отнимает энергию. Лучше сохраните душевный покой. Идеальная дружба этого года — редкие встречи, глубокие разговоры, взаимопомощь, принятие. Будьте благодарны друзьям, которые уходят, и тем, кто остаётся.',
        
        'health' => 'Здоровье в году девятки требует внимания к психосоматике. Стрессы, переживания, чувство вины могут вызвать хронические болезни, обострения. Займитесь очищением организма: диета, пост, детокс, отказ от вредных привычек. Обратитесь к психологу или психотерапевту. Йога, медитации, дыхательные практики помогут справиться с эмоциями. Внимание на пищеварительную систему (стресс вызывает гастриты, язвы). Также уязвимы кожа (аллергии, сыпи) и нервная система (неврозы, депрессии). Режим дня: обязателен, особенно сон. Не переутомляйтесь, избегайте шумных мероприятий. Лечение хронических болезней: завершите курсы. Диета: растительная, лёгкая, больше воды. Алкоголь — исключить. Курение — бросить. Займитесь профилактикой: проверьте все органы. Хороши санатории, особенно с психосоматическим уклоном. Психическое здоровье: ведите дневник, плачьте, если хочется, не держите эмоции в себе. Прощение — лучшая терапия. Если чувствуете безысходность, обратитесь к психологу, не стесняйтесь.',
        
        'creativity' => 'Творчество в году девятки — это итоговое творчество. Создавайте то, что подводит черту: завершайте циклы стихов, пишите последнюю главу, сочиняйте финальную песню. Творите для души, а не для денег. Искусство должно быть глубоким, философским, может быть трагическим. Хорошо для автобиографических произведений, мемуаров. Не бойтесь быть откровенным. Посещайте выставки, концерты, спектакли — для вдохновения. Если вы коллекционировали, продайте или передайте коллекцию. Творчество как способ прощания: напишите письма уходящим людям, нарисуйте образы уходящего периода. Если вы не умеете рисовать, используйте коллажи, фотографии. Творческие вечера в узком кругу единомышленников. Избегайте шумных премьер и презентаций. Не коммерциализируйте творчество в этом году. Ваш зритель — это вы сами и близкие, которые вас понимают. В конце года уничтожьте (сожгите, выбросьте) то, что считаете неудачным, оставьте только лучшее.',
        
        'learning' => 'Обучение в году девятки — это интеграция знаний. Не начинайте изучать новое, лучше систематизируйте старое. Напишите итоговую работу, создайте портфолио, систематизируйте заметки. Если вы учились чему-то 9 лет, сейчас время сдать экзамен, защитить диплом. Хорошо для курсов по психологии, философии, истории, религиоведению, искусству. Не подходят технические, практические навыки (программирование, дизайн). Учитесь у жизни, у событий, которые происходят. Рефлексируйте. Если вы преподаватель, помогайте ученикам завершить обучение, отпускайте их. Читайте книги по саморазвитию, но не гонитесь за новинками, перечитывайте классику. Лучшая форма обучения — самоанализ, медитация, ведение дневника. Не ходите на тренинги, где "качают навыки" — сейчас не до них. Учитесь прощать, отпускать, сострадать. Это главные "предметы" года.',
        
        'spirituality' => 'Духовность — главная тема года. Вы будете подводить духовные итоги 9-летнего цикла. Какие уроки извлекли? Насколько выросли? Что поняли? Простите себя и других. Посещайте церкви, храмы, но не для обрядов, а для тишины и принятия. Возможно, вы примете крещение или другую религию. Занимайтесь благотворительностью: помогайте деньгами, вещами, временем. Волонтёрство в хосписах, детских домах — это духовная практика года. Почитайте предков, ухаживайте за могилами. Практикуйте медитации на принятие и отпускание. Читайте духовную литературу, жития святых. Молитесь. Поститесь. Духовная задача: научиться безусловной любви и принятию. Принять мир таким, какой он есть, и себя в нём. Понять, что все мы — часть единого целого. Простить себя за ошибки и других за их. Отпустить прошлое и открыться будущему. В конце года, в декабре, проведите ритуал прощания со старым циклом. Поблагодарите Вселенную за всё, что было. И скажите "Да" новому циклу.',
        
        // === 4. ВРЕМЕННАЯ РАЗВЁРТКА ===
        
        
        'quarters' => [
            1 => 'Первый квартал (январь-март). Время завершения, прощения, очищения. Энергия идёт на спад. Заканчивайте дела, раздавайте долги, прощайте. Не начинайте нового.',
            2 => 'Второй квартал (апрель-июнь). Период помощи, творчества, итогов. Помогайте другим, творите для души, подводите итоги. Делайте уборку.',
            3 => 'Третий квартал (июль-сентябрь). Кульминация года. Завершайте главные проекты, прощайте главные обиды, отпускайте главное. Сентябрь — пик.',
            4 => 'Четвёртый квартал (октябрь-декабрь). Время отдыха, планирования нового цикла. Не начинайте нового, просто планируйте. Благодарите и прощайтесь со старым.'
        ],
        
        'good_days' => 'Благоприятные дни: 9, 18, 27 числа каждого месяца. В эти дни энергия завершения наиболее сильна. Рекомендуется: завершать проекты, просить прощения, отдавать долги, заниматься благотворительностью, медитировать, уединяться.',
        'bad_days' => 'Сложные дни: 3, 12, 21, 30 числа каждого месяца. Возможны депрессии, ссоры, чувство вины. Не начинайте нового, избегайте конфликтов, не принимайте важных решений. Посвятите день отдыху.',
        
        // === 5. ПРАКТИКУМ ===
        'affirmations' => [
            'Я с благодарностью отпускаю прошлое. Оно дало мне бесценный опыт.',
            'Я прощаю себя и всех, кто меня обидел. Прощение освобождает меня.',
            'Я завершаю то, что начал(а). Я освобождаю место для нового.',
