function getUltimateInterpretation($number) {
    global $yearUltimateInterpretations;
    $num = $number;
    if ($num == 11) $num = 2;
    if ($num == 22) $num = 4;
    if ($num == 33) $num = 6;
    return $yearUltimateInterpretations[$num] ?? $yearUltimateInterpretations[1];
}

